using Janseon.Core.Battle.Contracts;
namespace Janseon.Core.Battle.Sim { public static class OutcomeRules { public static void Resolve(BattleSimState s) { if(s.Tick + 1 >= BattleRules.MaxTicks){s.Outcome=Janseon.Core.Battle.Contracts.BattleOutcomeKind.Draw;return;} bool p=false,e=false; for(var i=0;i<s.Units.Length;i++){var u=s.Units[i];if(u.State!="Down"&&u.State!="Routing"){if(u.Side==0)p=true;else e=true;}} if(!p&&!e)s.Outcome=Janseon.Core.Battle.Contracts.BattleOutcomeKind.Ongoing; else if(!e)s.Outcome=Janseon.Core.Battle.Contracts.BattleOutcomeKind.PlayerVictory; else if(!p)s.Outcome=Janseon.Core.Battle.Contracts.BattleOutcomeKind.EnemyVictory; } } }
